"""Argparse argument definitions for the ``rasa tools`` command family."""

import argparse

from rasa.cli.tools.constants import (
    DEFAULT_RASA_SERVER_URL,
    ENGINE_CALM,
    MCP_TOOLS_DEFAULT_PORT,
    MCP_TOOLS_RASA_PROJECT_FOLDER_ENV_VAR,
    MCP_TOOLS_TRANSPORT_HTTP,
    MCP_TOOLS_TRANSPORT_STDIO,
    SUPPORTED_ENGINES,
    SUPPORTED_IDES,
)


def set_tools_docs_arguments(parser: argparse.ArgumentParser) -> None:
    """Arguments for `rasa tools init docs`."""
    parser.add_argument(
        "engine",
        nargs="?",
        type=str,
        choices=list(SUPPORTED_ENGINES),
        default=ENGINE_CALM,
        help=(
            "Rasa engine to fetch documentation for. "
            f"Defaults to '{ENGINE_CALM}', the historical behaviour."
        ),
    )
    parser.add_argument(
        "--project-path",
        type=str,
        default=None,
        dest="project_path",
        help=(
            "Path to the Rasa project folder. "
            "Defaults to the current directory when not specified."
        ),
    )
    parser.add_argument(
        "--yes",
        "-y",
        action="store_true",
        default=False,
        dest="yes",
        help="Skip confirmation prompts and overwrite existing docs.",
    )


def set_tools_skills_arguments(parser: argparse.ArgumentParser) -> None:
    """Shared skills-install arguments.

    Used by both `rasa tools skills install` and the deprecated
    `rasa tools init skills`.
    """
    parser.add_argument(
        "--yes",
        "-y",
        action="store_true",
        default=False,
        dest="yes",
        help="Skip confirmation prompts and accept defaults.",
    )
    parser.add_argument(
        "--project-path",
        type=str,
        default=None,
        dest="project_path",
        help=(
            "Path to the Rasa project folder. "
            "Defaults to the current directory when not specified."
        ),
    )
    parser.add_argument(
        "--ides",
        type=str,
        default=None,
        dest="ides",
        help=(
            "Comma-separated list of IDEs to install skills for: "
            f"{', '.join(SUPPORTED_IDES)}. "
            "If omitted, reads from the saved configuration."
        ),
    )


def set_tools_skills_install_arguments(parser: argparse.ArgumentParser) -> None:
    """Arguments for `rasa tools skills install`."""
    parser.add_argument(
        "engine",
        nargs="?",
        type=str,
        choices=list(SUPPORTED_ENGINES),
        default=None,
        help=(
            "Rasa engine to install skills for: 'mantle' (vendored) or "
            "'calm' (GitHub fetch). Prompted interactively when omitted."
        ),
    )
    set_tools_skills_arguments(parser)


def set_tools_skills_list_arguments(parser: argparse.ArgumentParser) -> None:
    """Arguments for `rasa tools skills list`."""
    parser.add_argument(
        "engine",
        nargs="?",
        type=str,
        choices=list(SUPPORTED_ENGINES),
        default=None,
        help=("Engine to list skills for. Lists both engines when omitted."),
    )


def set_tools_init_arguments(parser: argparse.ArgumentParser) -> None:
    """Arguments for the interactive setup wizard via `rasa tools init`.

    The wizard collects all configuration values interactively, or applies
    defaults in `--yes` mode.  When ``--yes`` is combined with explicit
    flags the wizard is skipped entirely and values are taken from the CLI.
    """
    parser.add_argument(
        "--yes",
        "-y",
        action="store_true",
        default=False,
        dest="yes",
        help="Accept all defaults and skip interactive prompts.",
    )
    parser.add_argument(
        "--project-path",
        type=str,
        default=None,
        dest="project_path",
        help=(
            "Path to the Rasa project folder. "
            "Defaults to the current directory when not specified."
        ),
    )
    parser.add_argument(
        "--mode",
        type=str,
        choices=[MCP_TOOLS_TRANSPORT_STDIO, MCP_TOOLS_TRANSPORT_HTTP],
        default=None,
        dest="mode",
        help=(
            "Transport mode for the MCP server. "
            f"Defaults to '{MCP_TOOLS_TRANSPORT_STDIO}'."
        ),
    )
    parser.add_argument(
        "--port",
        type=int,
        default=None,
        dest="port",
        help=(
            "Port for the MCP server in http mode. "
            f"Defaults to {MCP_TOOLS_DEFAULT_PORT}."
        ),
    )
    parser.add_argument(
        "--ides",
        type=str,
        default=None,
        dest="ides",
        help=(
            "Comma-separated list of IDEs to configure: "
            f"{', '.join(SUPPORTED_IDES)}."
        ),
    )
    parser.add_argument(
        "--skills",
        action="store_true",
        default=False,
        dest="skills",
        help="Install Rasa agent skills for the selected IDEs.",
    )
    parser.add_argument(
        "--engine",
        type=str,
        choices=list(SUPPORTED_ENGINES),
        default=None,
        # Not "engine": the `docs` subcommand's positional engine would overwrite
        # it, since argparse copies subcommand values over the parent's.
        dest="init_engine",
        help=(
            "Rasa engine to fetch docs and install agent skills for. Detected "
            f"from the project layout when omitted, falling back to '{ENGINE_CALM}'. "
            "Applies to the setup wizard only; `rasa tools init docs` takes its "
            "own engine argument."
        ),
    )
    parser.add_argument(
        "--rasa-server-url",
        type=str,
        default=None,
        dest="rasa_server_url",
        help=(
            "Base URL of the running Rasa server " f"(e.g. {DEFAULT_RASA_SERVER_URL})."
        ),
    )


def set_tools_status_arguments(parser: argparse.ArgumentParser) -> None:
    """Arguments for `rasa tools status`."""
    parser.add_argument(
        "--project-path",
        type=str,
        default=None,
        dest="project_path",
        help=(
            "Path to the Rasa project folder. "
            "Defaults to the current directory when not specified."
        ),
    )


def set_tools_run_arguments(parser: argparse.ArgumentParser) -> None:
    """Arguments for running the Rasa MCP tools server via `rasa tools run`."""
    parser.add_argument(
        "--project-path",
        type=str,
        default=None,
        dest="project_path",
        help=(
            "Path to the Rasa project folder. Falls back to the "
            f"{MCP_TOOLS_RASA_PROJECT_FOLDER_ENV_VAR} environment variable, then the "
            "current directory. Cannot be used together with --config."
        ),
    )
    parser.add_argument(
        "--mode",
        type=str,
        choices=[MCP_TOOLS_TRANSPORT_STDIO, MCP_TOOLS_TRANSPORT_HTTP],
        default=None,
        dest="mode",
        help=(
            "Transport mode for the MCP server. "
            f"Defaults to '{MCP_TOOLS_TRANSPORT_STDIO}' when not specified. "
            f"'{MCP_TOOLS_TRANSPORT_STDIO}' is the standard for IDE integrations "
            "(requires stdout to contain ONLY JSON-RPC messages — all logging goes "
            f"to stderr); '{MCP_TOOLS_TRANSPORT_HTTP}' starts a network listener. "
            "Cannot be used together with --config."
        ),
    )
    parser.add_argument(
        "--port",
        type=int,
        default=None,
        dest="port",
        help=(
            "Port for the MCP server in http mode. "
            f"Defaults to {MCP_TOOLS_DEFAULT_PORT} when not specified. "
            "Cannot be used together with --config."
        ),
    )
    parser.add_argument(
        "--rasa-server-url",
        type=str,
        default=None,
        dest="rasa_server_url",
        help=(
            "Base URL of the running Rasa server "
            f"(e.g. {DEFAULT_RASA_SERVER_URL}). "
            "Tells the MCP server where to reach the Rasa assistant. "
            f"Defaults to {DEFAULT_RASA_SERVER_URL}. "
            "Cannot be used together with --config."
        ),
    )
    parser.add_argument(
        "--config",
        type=str,
        default=None,
        dest="config",
        help="Path to a run configuration file or directory containing "
        ".rasa/tools.yaml. When provided, all settings are loaded from this "
        "file. Cannot be combined with --mode, --port, or --project-path.",
    )
